"""Build the source-only E2-O03 reconciliation; never imports source modules."""
import hashlib
import json
from pathlib import Path

OUT = Path(__file__).resolve().parent
REPO = OUT.parents[3]
SOURCE = Path('/Users/carlos/Documents/Drogon-mentu-session')
PREFIX = {'R': 'src/renderer/src/', 'M': 'src/main/', 'S': 'src/shared/'}
REVISION = 'c97906287bb7a390b25e2025b600d9fb3c25d9c3'
refs = {}
tests = {}
rows = {}


def ref(spec):
    path, bounds = spec.rsplit(':', 1)
    path = PREFIX[path[0]] + path[2:]
    raw = (SOURCE / path).read_bytes()
    lines = raw.splitlines(keepends=True)
    start, end = bounds.split('-') if '-' in bounds else (bounds, bounds)
    start, end = int(start), len(lines) if end == '*' else int(end)
    assert 1 <= start <= end <= len(lines), (spec, len(lines))
    key = f'{path}:{start}-{end}'
    refs[key] = {
        'path': path, 'startLine': start, 'endLine': end,
        'fileSha256': hashlib.sha256(raw).hexdigest(),
        'rangeSha256': hashlib.sha256(b''.join(lines[start-1:end])).hexdigest(),
        'readScope': 'cited body/range; not a claim that every other line in the file was read',
    }
    return key


def rr(*specs):
    return [ref(x) for x in specs]


def test(key, spec, assertion, level, extra=()):
    tests[key] = {'references': rr(spec, *extra), 'assertionBodyAssociation': assertion,
                  'evidenceLevel': level, 'executedThisDispatch': False}


def action(aid, families, source, eligibility, event, effects, branches, acceptance, tested=(), status='traced'):
    assert aid not in rows
    rows[aid] = dict(id=aid, routingFamilies=families.split(), effectReferences=rr(*source),
                    eligibility=eligibility, eventHandling=event, parametersAndEffects=effects,
                    failureNoopAndVariantBranches=branches, sourceDisposition=status,
                    reviewedAssertionAssociations=list(tested),
                    assertionOmission=None if tested else 'No action-specific assertion body associated in this review; not a claim that no test exists anywhere.',
                    remainingAcceptance=acceptance)


